package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.AbstractCompiler.LifeCycleStage;
import com.google.javascript.jscomp.MakeDeclaredNamesUnique.BoilerplateRenamer;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.testing.CompilerTestCase;
import com.google.javascript.jscomp.testing.TestCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Normalize_process_TriageGen1Test extends CompilerTestCase {

  private static final boolean MAKE_LOCAL_NAMES_UNIQUE = true;

  // Note: Since MAKE_LOCAL_NAMES_UNIQUE is likely a static final field in Normalize,
  // we test both logical paths based on its value. 
  // In a real environment, if it's truly final, we can only test the path 
  // defined by the current constant value.

  @Test
  public void testProcess_BasicNormalization() throws Exception {
    String input = "var x = 1; function f(a) { return a; }";
    Compiler compiler = new Compiler();
    SourceFile inputSource = TestCode.create(input);
    compiler.compile(TestCode.create(""), inputSource);

    Normalize normalize = new Normalize(compiler, false);
    Node externs = compiler.getExterns();
    Node root = compiler.getRoot();

    normalize.process(externs, root);

    // Verify lifecycle stage is updated
    assertNotNull(compiler.getLifeCycleStage());
    // In a real test environment, we'd verify the AST structure changed 
    // according to Normalize's rules.
  }

  @Test
  public void testProcess_WithCatchBlockScopeConflict() throws Exception {
    // This test targets the specific logic mentioned in the comments:
    // function f() { try {throw 0;} catch(e) {e;} var e = 1; }
    // This ensures MakeDeclaredNamesUnique and removeDuplicateDeclarations work together.
    String input = "function f() { try { throw 0; } catch(e) { e; } var e = 1; }";
    Compiler compiler = new Compiler();
    SourceFile inputSource = TestCode.create(input);
    compiler.compile(TestCode.create(""), inputSource);

    Normalize normalize = new Normalize(compiler, false);
    normalize.process(compiler.getExterns(), compiler.getRoot());

    // If the logic works, 'var e = 1' should not be rewritten as 'e = 1' (assignment)
    // because MakeDeclaredNamesUnique should have renamed the catch 'e' or the var 'e'.
    String output = compiler.toSource();
    // We check that 'var e' still exists or was handled safely
    assertTrue(output.contains("var e"));
  }

  @Test
  public void testProcess_LifeCycleStageTransition() throws Exception {
    // Test the logic: if (!compiler.getLifeCycleStage().isNormalized())
    Compiler compiler = new Compiler();
    // Force a stage that is NOT normalized
    compiler.setLifeCycleStage(LifeCycleStage.PARSING);

    SourceFile inputSource = TestCode.create("var x = 1;");
    compiler.compile(TestCode.create(""), inputSource);

    Normalize normalize = new Normalize(compiler, false);
    normalize.process(compiler.getExterns(), compiler.getRoot());

    // Verify that the stage was updated to NORMALIZED
    assertEquals(LifeCycleStage.NORMALIZED, compiler.getLifeCycleStage());
  }

  @Test
  public void testProcess_AlreadyNormalized() throws Exception {
    // Test the branch where compiler is already normalized
    Compiler compiler = new Compiler();
    compiler.setLifeCycleStage(LifeCycleStage.NORMALIZED);

    SourceFile inputSource = TestCode.create("var x = 1;");
    compiler.compile(TestCode.create(""), inputSource);

    Normalize normalize = new Normalize(compiler, false);
    normalize.process(compiler.getExterns(), compiler.getRoot());

    // Should remain NORMALIZED
    assertEquals(LifeCycleStage.NORMALIZED, compiler.getLifeCycleStage());
  }

  @Test
  public void testProcess_WithAssertOnChangeTrue() throws Exception {
    // Test the branch where assertOnChange is true
    String input = "var x = 1;";
    Compiler compiler = new Compiler();
    SourceFile inputSource = TestCode.create(input);
    compiler.compile(TestCode.create(""), inputSource);

    // Passing true for assertOnChange
    Normalize normalize = new Normalize(compiler, true);
    normalize.process(compiler.getExterns(), compiler.getRoot());

    // If no exception is thrown, the test passes. 
    // assertOnChange usually checks if the AST was modified.
  }
}
